import json,re
from pathlib import Path
manifest=Path('/mnt/data/LSF/results/court/agentic_rule_full_data_gpt54mini_adaptive/all_docs/q07_on_what_date_was_this_opinion_filed.manifest.json')
obj=json.loads(manifest.read_text())
docs=obj['docs'] if isinstance(obj,dict) and 'docs' in obj else obj
patterns={}
examples={}
for d in docs:
    p=Path(d['doc_path'])
    try:
        lines=p.read_text(errors='ignore').splitlines()[:40]
    except Exception:
        continue
    for line in lines:
        s=line.strip()
        if re.search(r'"'^(FILED|Filed)'"\\b', s):
            key=s
            patterns[key]=patterns.get(key,0)+1
            examples.setdefault(key, d['doc_name'])
            break
print('unique filed-start patterns:', len(patterns))
for k,v in sorted(patterns.items(), key=lambda kv:(-kv[1], kv[0]))[:50]:
    print(v, examples[k], '::', k)
PY"

